package com.ecommerce.project.service;import com.ecommerce.project.exeptions.APIException;import com.ecommerce.project.exeptions.ResourceNotFoundException;import com.ecommerce.project.model.Category;import com.ecommerce.project.payload.CategoryDTO;import com.ecommerce.project.payload.CategoryResponse;import com.ecommerce.project.repositories.CategoryRepository;import org.modelmapper.ModelMapper;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.data.domain.Page;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Pageable;import org.springframework.data.domain.Sort;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.util.ArrayList;import java.util.List;import java.util.Optional;/** * The service class for implementing the operations related to categories. */@Servicepublic class CategoryServiceImpl implements CategoryService {    @Autowired    private CategoryRepository  categoryRepository;    @Autowired    private ModelMapper modelMapper;    /**     * Gets all the categories present in the database.     *     * @return List of categories present in the database.     */    @Override    public CategoryResponse getAllCategories(Integer pageNUmber, Integer pageSize, String sortBy, String sortOrder) {        Sort sortByAndOrder = sortOrder.equalsIgnoreCase("asc")                ? Sort.by(sortBy).ascending()                : Sort.by(sortBy).descending();        Pageable pageDetails = PageRequest.of(pageNUmber, pageSize,  sortByAndOrder);        Page<Category> categoryPage = categoryRepository.findAll(pageDetails);        List<Category> categories = categoryPage.getContent();        if (categories.isEmpty()) {            throw new APIException("No categories created till now.");        }        List<CategoryDTO> categoryDTO = categories.stream()                .map(category -> modelMapper.map(category, CategoryDTO.class))                .toList();        CategoryResponse categoryResponse = new CategoryResponse();        categoryResponse.setContent(categoryDTO);        categoryResponse.setPageNumber(categoryPage.getNumber());        categoryResponse.setPageSize(categoryPage.getSize());        categoryResponse.setTotalPages(categoryPage.getTotalPages());        categoryResponse.setTotalElements(categoryPage.getTotalElements());        categoryResponse.setLastPage(categoryPage.isLast());        return categoryResponse;    }    /**     * Creates a new category.     *     * @param categoryDTO The category to be created.     */    @Override    public CategoryDTO createCategory(CategoryDTO categoryDTO) {        Category category = modelMapper.map(categoryDTO, Category.class);        Category categoryFromDb = categoryRepository.findByCategoryName(category.getCategoryName());        if (categoryFromDb != null) {            throw new APIException("Category with name " + category.getCategoryName() + " already exists");        }        Category savedCategory = categoryRepository.save(category);        return modelMapper.map(savedCategory, CategoryDTO.class);    }    /**     * Deletes the category using the id of the category.     *     * @param categoryId The id of the category to be deleted.     *     * @return The message after the operation.     */    @Override    public CategoryDTO deleteCategory(Long categoryId) {        Category category = categoryRepository.findById(categoryId)                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Category not found"));        categoryRepository.delete(category);        return modelMapper.map(category, CategoryDTO.class);    }    /**     * Updates the category by using the id of the category.     *     * @param category The category to be updated.     * @param categoryId The id of the category that needs to be updated.     *     * @return The updated category.     */    @Override    public CategoryDTO updateCategory(CategoryDTO categoryDTO, Long categoryId){        Category savedCategory = categoryRepository.findById(categoryId)                .orElseThrow(() -> new ResourceNotFoundException("Category", "cateogryId", categoryId));        Category category = modelMapper.map(categoryDTO, Category.class);        category.setCategoryId(categoryId);        savedCategory =  categoryRepository.save(category);        return modelMapper.map(savedCategory, CategoryDTO.class);    }}